pub(crate) const PAGE: &str = r#"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="color-scheme" content="dark light">
  <title>Lenso Support Agent Workspace</title>
  <link rel="stylesheet" href="/support/assets/app.css">
</head>
<body>
  <div class="shell">
    <aside>
      <div class="brand"><span>L</span>Lenso Support Agent</div>
      <nav><button class="active">Inbox <b id="inbox-count">—</b></button><button>My cases</button><button>Waiting</button><button>Resolved</button></nav>
      <section class="connect"><label>Organization<input id="organization" placeholder="org_demo"></label><label>Bearer token<input id="token" type="password" placeholder="••••••••"></label><button id="connect">Open inbox</button><small id="connection-state">Not connected</small></section>
    </aside>
    <main>
      <header><div><p class="eyebrow">CUSTOMER CARE</p><h1>Support inbox</h1></div><button id="new-case">New case</button></header>
      <div class="toolbar"><select id="state-filter"><option value="">All states</option><option value="open">Open</option><option value="in_progress">In progress</option><option value="waiting_customer">Waiting customer</option><option value="resolved">Resolved</option><option value="closed">Closed</option></select><input id="requester-filter" placeholder="Requester subject"><input id="assignee-filter" placeholder="Assignee subject"><button id="apply" class="secondary">Apply filters</button></div>
      <section class="inbox">
        <div class="case-list"><div id="cases"><div class="empty">Connect to load the case inbox.</div></div><button id="more" class="secondary hidden">Load more</button></div>
        <article id="case-detail" class="case-detail empty-detail"><span>◯</span><h2>Select a support case</h2><p>Review context, collaborate privately, and reply to the requester.</p></article>
      </section>
    </main>
  </div>
  <dialog id="case-dialog"><form id="case-form"><div class="dialog-head"><div><p class="eyebrow">NEW REQUEST</p><h2>Create support case</h2></div><button type="button" class="close secondary">×</button></div><label>Title<input name="title" required maxlength="200"></label><label>Description<textarea name="description" rows="5" required maxlength="10000"></textarea></label><label>Priority<select name="priority"><option>normal</option><option>low</option><option>high</option><option>urgent</option></select></label><p id="form-error" class="error"></p><div class="dialog-actions"><button type="button" class="close secondary">Cancel</button><button type="submit">Create case</button></div></form></dialog>
  <div id="toast" role="status" aria-live="polite"></div>
  <script src="/support/assets/app.js" defer></script>
</body>
</html>"#;

pub(crate) const CSS: &str = r#":root{font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#eff0f4;background:#0d1012;--panel:#15191c;--panel2:#1a1f23;--line:#293035;--muted:#8e989f;--accent:#45b59c;--warn:#e7a65b}*{box-sizing:border-box}body{margin:0;min-width:980px;background:radial-gradient(circle at 68% -15%,#153b37 0,transparent 34%),#0d1012}.shell{display:grid;grid-template-columns:226px 1fr;min-height:100vh}aside{position:sticky;top:0;height:100vh;padding:23px 14px;border-right:1px solid var(--line);background:#101416eF;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:10px;font-weight:700;padding:0 9px 28px}.brand span{display:grid;place-items:center;width:29px;height:29px;border-radius:9px;background:linear-gradient(145deg,#48c3a7,#267a6a);box-shadow:0 8px 24px #2d9f8544}nav{display:grid;gap:5px}button,input,select,textarea{font:inherit;color:#eef1f2;border:1px solid var(--line);border-radius:8px;background:#1b2024}button{padding:9px 12px;border:0;background:var(--accent);color:#071310;font-weight:650;cursor:pointer}button:hover{filter:brightness(1.08)}button.secondary{color:#cbd1d4;background:#20262a;border:1px solid #31393f}nav button{display:flex;justify-content:space-between;text-align:left;color:#a6afb4;background:transparent}nav button.active,nav button:hover{background:#20262a;color:white}nav b{font-size:10px;color:#78ccb8}.connect{margin-top:auto;padding:14px 9px 2px;border-top:1px solid var(--line);display:grid;gap:10px}.connect label,dialog label{display:grid;gap:6px;font-size:11px;color:#9da6ab}.connect input,input,select,textarea{padding:9px 10px;outline:none}.connect input{width:100%}.connect small{color:var(--muted)}input:focus,select:focus,textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px #45b59c20}main{padding:29px 34px 45px;min-width:0}header{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}h1{font-size:28px;letter-spacing:-.035em;margin:0}.eyebrow{margin:0 0 6px;color:#6bd1ba;font-size:10px;font-weight:750;letter-spacing:.16em}.toolbar{display:grid;grid-template-columns:170px 1fr 1fr auto;gap:9px;margin-bottom:13px}.inbox{display:grid;grid-template-columns:minmax(340px,.8fr) minmax(520px,1.2fr);min-height:650px;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--panel)}.case-list{border-right:1px solid var(--line);padding:12px}.case-row{padding:14px 13px;border:1px solid transparent;border-radius:10px;cursor:pointer}.case-row:hover,.case-row.selected{background:#20262a;border-color:#30383d}.case-row-top{display:flex;justify-content:space-between;gap:12px}.case-row h3{font-size:13px;margin:0}.case-row time{font-size:10px;color:#758087}.case-row p{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin:7px 0 9px}.meta{display:flex;gap:6px;align-items:center}.badge{display:inline-flex;align-items:center;padding:4px 7px;border-radius:999px;border:1px solid #354047;color:#aeb7bc;font-size:9px;text-transform:uppercase;letter-spacing:.05em}.badge.urgent{color:#f0aaa3;border-color:#6b3936}.case-detail{padding:24px;min-width:0}.empty,.empty-detail{text-align:center;color:var(--muted);padding:70px 15px}.empty-detail{display:grid;place-items:center;align-content:center}.empty-detail span{font-size:32px;color:#65c8b2}.empty-detail h2{font-size:17px;color:#dfe3e5;margin:12px 0 4px}.empty-detail p{margin:0;max-width:400px}.detail-head{display:flex;justify-content:space-between;gap:20px;padding-bottom:18px;border-bottom:1px solid var(--line)}.detail-head h2{font-size:21px;margin:8px 0}.detail-head p{color:#a5aeb3;font-size:12px;line-height:1.5;margin:0}.case-actions{display:flex;gap:7px;align-items:flex-start}.case-actions select,.case-actions input{max-width:150px}.timeline{display:grid;gap:10px;margin:20px 0}.message{padding:13px;border:1px solid var(--line);border-radius:10px;background:#181d20}.message.internal{border-color:#54452f;background:#211e19}.message header{margin:0 0 8px}.message strong{font-size:11px}.message time{font-size:10px;color:var(--muted)}.message p{font-size:12px;line-height:1.55;margin:0;white-space:pre-wrap}.composer{display:grid;gap:8px;padding-top:14px;border-top:1px solid var(--line)}.composer-row{display:flex;justify-content:space-between;gap:8px}.hidden{display:none!important}#more{width:100%;margin-top:10px}dialog{width:min(560px,calc(100vw - 40px));padding:0;color:#eef0f2;background:#171c1f;border:1px solid #343d42;border-radius:14px;box-shadow:0 30px 100px #000b}dialog::backdrop{background:#07090bbb;backdrop-filter:blur(3px)}dialog form{padding:24px;display:grid;gap:14px}.dialog-head{display:flex;justify-content:space-between}.dialog-head h2{margin:0;font-size:22px}.dialog-actions{display:flex;justify-content:flex-end;gap:8px}.error{min-height:14px;color:#f0958c;margin:0;font-size:12px}#toast{position:fixed;right:24px;bottom:24px;opacity:0;transform:translateY(16px);padding:11px 14px;border:1px solid #3b454b;border-radius:9px;background:#20262a;transition:.2s;font-size:12px}#toast.show{opacity:1;transform:none}@media(max-width:1120px){.inbox{grid-template-columns:390px 1fr}}"#;

pub(crate) const JS: &str = r#"const $=s=>document.querySelector(s);const state={cases:[],cursor:null,selected:null};const org=()=>$('#organization').value.trim();
function query(values){const q=new URLSearchParams();Object.entries(values).forEach(([k,v])=>{if(v!==undefined&&v!==null&&v!=='')q.set(k,String(v))});return q.toString()}
function headers(json=false){const h={};const token=$('#token').value.trim();if(token)h.Authorization=`Bearer ${token}`;if(json)h['Content-Type']='application/json';return h}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{...headers(Boolean(options.body)),...(options.headers||{})}});if(!response.ok){let problem={};try{problem=await response.json()}catch{}throw new Error(problem.detail||`${response.status} ${response.statusText}`)}if(response.status===204)return null;return response.json()}
function escape(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function filters(cursor=null){return{organization_id:org(),state:$('#state-filter').value,requester_subject:$('#requester-filter').value.trim(),assignee_subject:$('#assignee-filter').value.trim(),cursor,limit:40}}
async function loadCases(append=false){if(!org())throw new Error('Organization is required.');const data=await api(`/api/support/cases?${query(filters(append?state.cursor:null))}`);state.cases=append?[...state.cases,...data.cases]:data.cases;state.cursor=data.next_cursor;renderCases();$('#inbox-count').textContent=state.cases.length;$('#more').classList.toggle('hidden',!state.cursor)}
function renderCases(){const host=$('#cases');if(!state.cases.length){host.innerHTML='<div class="empty">No cases match these filters.</div>';return}host.innerHTML=state.cases.map(item=>`<article class="case-row ${state.selected===item.case_id?'selected':''}" data-id="${escape(item.case_id)}"><div class="case-row-top"><h3>${escape(item.identifier)} · ${escape(item.title)}</h3><time>${escape(item.updated_at.slice(0,10))}</time></div><p>${escape(item.description)}</p><div class="meta"><span class="badge">${escape(item.state)}</span><span class="badge ${escape(item.priority)}">${escape(item.priority)}</span><span class="badge">${escape(item.assignee_subject||'unassigned')}</span></div></article>`).join('');host.querySelectorAll('[data-id]').forEach(el=>el.addEventListener('click',()=>selectCase(el.dataset.id)))}
async function selectCase(id){state.selected=id;renderCases();const detail=await api(`/api/support/cases/${encodeURIComponent(id)}?${query({organization_id:org()})}`);const messages=await api(`/api/support/cases/${encodeURIComponent(detail.case_id)}/messages?${query({organization_id:org(),limit:100})}`);const host=$('#case-detail');host.className='case-detail';host.innerHTML=`<div class="detail-head"><div><div class="meta"><span class="badge">${escape(detail.identifier)}</span><span class="badge ${escape(detail.priority)}">${escape(detail.priority)}</span></div><h2>${escape(detail.title)}</h2><p>${escape(detail.description)}</p></div><div class="case-actions"><select id="next-state"><option>open</option><option>in_progress</option><option>waiting_customer</option><option>resolved</option><option>closed</option></select><button id="transition" class="secondary">Set state</button></div></div><div class="timeline">${messages.messages.map(message=>`<article class="message ${message.visibility==='internal'?'internal':''}"><header><strong>${escape(message.author_subject)} · ${escape(message.visibility)}</strong><time>${escape(message.created_at)}</time></header><p>${escape(message.body)}</p></article>`).join('')||'<div class="empty">No messages yet.</div>'}</div><form id="composer" class="composer"><textarea name="body" rows="3" required placeholder="Write a reply or internal note…"></textarea><div class="composer-row"><select name="visibility"><option value="public">Public reply</option><option value="internal">Internal note</option></select><button type="submit">Send</button></div></form>`;$('#next-state').value=detail.state;$('#transition').addEventListener('click',()=>transition(detail).catch(e=>toast(e.message)));$('#composer').addEventListener('submit',e=>{e.preventDefault();addMessage(detail,e.currentTarget).catch(error=>toast(error.message))})}
async function transition(detail){const stateValue=$('#next-state').value;await api(`/api/support/cases/${encodeURIComponent(detail.case_id)}/transition`,{method:'POST',body:JSON.stringify({organization_id:org(),case_id:detail.case_id,state:stateValue,reason:null,expected_revision:detail.revision,idempotency_key:crypto.randomUUID()})});await loadCases();await selectCase(detail.case_id);toast('Case state updated')}
async function addMessage(detail,form){const values=Object.fromEntries(new FormData(form));const segment=values.visibility==='internal'?'notes':'messages';await api(`/api/support/cases/${encodeURIComponent(detail.case_id)}/${segment}`,{method:'POST',body:JSON.stringify({organization_id:org(),case_id:detail.case_id,visibility:values.visibility,body:values.body,expected_revision:detail.revision,idempotency_key:crypto.randomUUID()})});await selectCase(detail.case_id);toast(values.visibility==='internal'?'Internal note added':'Reply sent')}
async function createCase(form){const values=Object.fromEntries(new FormData(form));const created=await api('/api/support/cases',{method:'POST',body:JSON.stringify({organization_id:org(),title:values.title,description:values.description,priority:values.priority,idempotency_key:crypto.randomUUID()})});$('#case-dialog').close();form.reset();await loadCases();await selectCase(created.case_id);toast('Support case created')}
async function connect(){try{$('#connection-state').textContent='Loading…';await loadCases();$('#connection-state').textContent='Connected';toast('Inbox loaded')}catch(error){$('#connection-state').textContent='Connection failed';toast(error.message)}}
$('#connect').addEventListener('click',connect);$('#apply').addEventListener('click',()=>loadCases().catch(e=>toast(e.message)));$('#more').addEventListener('click',()=>loadCases(true).catch(e=>toast(e.message)));$('#new-case').addEventListener('click',()=>$('#case-dialog').showModal());document.querySelectorAll('.close').forEach(el=>el.addEventListener('click',()=>$('#case-dialog').close()));$('#case-form').addEventListener('submit',e=>{e.preventDefault();$('#form-error').textContent='';createCase(e.currentTarget).catch(error=>$('#form-error').textContent=error.message)});['organization','token'].forEach(id=>{const saved=localStorage.getItem(`lenso.support.${id}`);if(saved)$(`#${id}`).value=saved;$(`#${id}`).addEventListener('change',e=>localStorage.setItem(`lenso.support.${id}`,e.target.value))});"#;
